AW = [("2026-01", 31, 74410, 100910, 1010993), ("2026-02", 28, 70994, 85508, 814195), ("2026-03", 31, 68902, 91327, None),
      ("2026-04", 30, 48780, 64227, None), ("2026-05", 31, 33322, 55297, None), ("2026-06", 30, 24510, 44046, 472834)]
